<?php
namespace App\Http\Controllers\Api; use App\Http\Controllers\Controller; use App\Models\Payment; use App\Models\Sale; use App\Models\Tenant; use Illuminate\Http\Request;
class PaymentController extends Controller { public function store(Request $r,Tenant $t,Sale $sale){abort_unless($sale->tenant_id===$t->id,404);$d=$r->validate(['amount'=>['required','numeric','gt:0'],'method'=>['required','string','max:30'],'reference'=>['nullable','string'],'paid_at'=>['nullable','date']]); if((float)$d['amount']>(float)$sale->balance) abort(422,'El pago supera el saldo pendiente.');$d+=['tenant_id'=>$t->id,'created_by'=>$r->user()->id];$payment=$sale->payments()->create($d);return response()->json(['data'=>$payment,'paid_amount'=>$sale->fresh()->paid_amount,'balance'=>$sale->fresh()->balance],201);} }
